let state = $json.case_state;
if (typeof state === 'string') {
  try { state = JSON.parse(state); } catch (error) {
    state = { workflow_status: 'HUMAN_ESCALATION', input_error: error.message };
  }
}
const addTrace = (state, component, event, status, details = {}) => {
  if (!state.debug_trace_enabled) return;
  if (!Array.isArray(state.debug_trace)) state.debug_trace = [];
  const normalizedStatus = status === 'SUCCESS' ? 'OK' : status === 'STARTED' ? 'START' : status === 'FAILURE' ? 'ERROR' : status;
  state.debug_trace.push({
    seq: state.debug_trace.length + 1,
    timestamp: new Date().toISOString(),
    component,
    event,
    status: normalizedStatus,
    iteration: Number(state.iteration ?? 0),
    details
  });
};
const endpointHost = String($json.nebius_endpoint ?? '').replace(/^https?:\/\//, '').split('/')[0] || null;
addTrace(state, 'ORCHESTRATOR', 'NEBIUS_REQUEST_PREPARED', 'OK', {
  model_configured: Boolean(String($json.nebius_model ?? '').trim()),
  auth_configured: Boolean(String($env.NEBIUS_API_KEY ?? '').trim()),
  endpoint_host: endpointHost,
  temperature: Number($json.temperature ?? 0),
  reasoning_effort: 'low',
  max_completion_tokens: 1200,
  response_format_type: 'json_object',
  message_count: 2,
  request_body_keys: ['model', 'temperature', 'reasoning_effort', 'max_completion_tokens', 'response_format', 'messages']
});
const promptState = JSON.parse(JSON.stringify(state));
delete promptState.debug_trace;
delete promptState.debug_trace_enabled;
const systemPrompt = "You coordinate a healthcare payer member servicing investigation. Use only facts already present in case_state. Never invent payer facts. Choose exactly one minimum next decision from: CHECK_ELIGIBILITY, CHECK_BENEFITS, CHECK_CLAIMS, CHECK_AUTHORIZATION, CHECK_AUTHORIZATION_ALTERNATE, CHECK_PROVIDER, RESOLVE, HUMAN_ESCALATION. Do not repeat a successful tool call unless a documented recovery condition requires it. Treat deterministic NOT_FOUND as conclusive evidence, not a retryable error. Do not repeat the same deterministic lookup after SUCCESS or NOT_FOUND. When authorization is NOT_FOUND for an inquiry about a prior-authorization denial, choose RESOLVE without checking Provider. Check eligibility first when unknown. Check benefits when coverage rules matter. Check claims for claim inquiries. Check authorization when prior authorization is required, a claim denial references authorization, or the inquiry concerns authorization. For SCN004, after one simulated authorization error retry with CHECK_AUTHORIZATION; after two errors choose CHECK_AUTHORIZATION_ALTERNATE. Check provider only when provider/network facts are needed or claim and authorization provider/location evidence conflicts. Before RESOLVE, if successful claim and authorization evidence conflict on provider or location and provider evidence is still unknown, choose CHECK_PROVIDER. For an INACTIVE coverage result with ACTIVE enrollment and stale synchronization evidence, do not call claims, authorization, or provider; resolve the eligibility mismatch. If enough evidence exists choose RESOLVE. If evidence cannot be safely obtained after allowed retries choose HUMAN_ESCALATION. Never diagnose, recommend treatment, perform a payer write, or select an arbitrary tool. Return JSON only with keys agent, status, decision, reason, required_inputs, error.";
return [{
  json: {
    ...$json,
    case_state: state,
    request_body: {
      model: $json.nebius_model,
      temperature: Number($json.temperature ?? 0),
      reasoning_effort: 'low',
      max_completion_tokens: 1200,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: 'Current case_state:\n' + JSON.stringify(promptState) }
      ]
    }
  }
}];

const buildContext = $('Build Orchestrator Request').first().json;
const state = JSON.parse(JSON.stringify(buildContext.case_state));
const addTrace = (state, component, event, status, details = {}) => {
  if (!state.debug_trace_enabled) return;
  if (!Array.isArray(state.debug_trace)) state.debug_trace = [];
  const normalizedStatus = status === 'SUCCESS' ? 'OK' : status === 'STARTED' ? 'START' : status === 'FAILURE' ? 'ERROR' : status;
  state.debug_trace.push({
    seq: state.debug_trace.length + 1,
    timestamp: new Date().toISOString(),
    component,
    event,
    status: normalizedStatus,
    iteration: Number(state.iteration ?? 0),
    details
  });
};
const allowed = new Set([
  'CHECK_ELIGIBILITY', 'CHECK_BENEFITS', 'CHECK_CLAIMS',
  'CHECK_AUTHORIZATION', 'CHECK_AUTHORIZATION_ALTERNATE',
  'CHECK_PROVIDER', 'RESOLVE', 'HUMAN_ESCALATION'
]);
let diagnostic = null;
const hasOwn = (value, key) => Boolean(
  value && typeof value === 'object' && Object.prototype.hasOwnProperty.call(value, key)
);
const normalizeContent = (value) => {
  if (typeof value === 'string') return value.trim() ? value : null;
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (!Array.isArray(value) || value.length === 0) return null;
  const textParts = [];
  for (const part of value) {
    if (typeof part === 'string') {
      textParts.push(part);
      continue;
    }
    if (!part || typeof part !== 'object' || Array.isArray(part)) return null;
    const keys = Object.keys(part);
    const explicitTextPart = (
      typeof part.text === 'string' &&
      (part.type === 'text' || part.type === 'output_text') &&
      keys.every(key => key === 'type' || key === 'text')
    );
    if (!explicitTextPart) return null;
    textParts.push(part.text);
  }
  const joined = textParts.join('').trim();
  return joined || null;
};
try {
  const received = $input.first().json;
  let normalizationPath = 'DIRECT';
  let response = received;
  if (received?.body !== null && received?.body !== undefined) { response = received.body; normalizationPath = 'BODY'; }
  else if (received?.data !== null && received?.data !== undefined) { response = received.data; normalizationPath = 'DATA'; }
  else if (received?.response !== null && received?.response !== undefined) { response = received.response; normalizationPath = 'RESPONSE'; }
  else if (received?.json !== null && received?.json !== undefined) { response = received.json; normalizationPath = 'JSON'; }
  if (typeof response === 'string') {
    const trimmedResponse = response.trim();
    if (trimmedResponse.startsWith('{') || trimmedResponse.startsWith('[')) {
      try { response = JSON.parse(trimmedResponse); normalizationPath += '+STRING_PARSED'; } catch (error) {}
    }
  }
  if (Array.isArray(response) && response.length === 1 && response[0] && typeof response[0] === 'object') {
    response = response[0];
    normalizationPath += '+ARRAY_FIRST_ITEM';
  }
  const responseIsObject = Boolean(response && typeof response === 'object' && !Array.isArray(response));
  const choices = responseIsObject && Array.isArray(response.choices) ? response.choices : [];
  const choice = choices[0];
  const message = choice && typeof choice.message === 'object' && !Array.isArray(choice.message) ? choice.message : null;
  const messageContentPresent = hasOwn(message, 'content') && message.content !== null && message.content !== undefined;
  const messageContent = messageContentPresent ? normalizeContent(message.content) : null;
  const textPresent = hasOwn(choice, 'text') && choice.text !== null && choice.text !== undefined;
  const fallbackContent = !messageContentPresent && textPresent ? normalizeContent(choice.text) : null;
  const content = messageContent ?? fallbackContent;
  const contentType = content === null ? 'missing' : (Array.isArray(content) ? 'array' : typeof content);
  const contentLength = typeof content === 'string' ? content.length : null;
  const contentSource = messageContent !== null
    ? (Array.isArray(message?.content) ? 'TEXT_ARRAY' : (typeof message?.content === 'object' ? 'OBJECT_CONTENT' : 'MESSAGE_CONTENT'))
    : (fallbackContent !== null ? 'CHOICE_TEXT' : null);
  const valueType = (value) => value === null ? 'null' : (Array.isArray(value) ? 'array' : typeof value);
  const objectKeys = (value) => value && typeof value === 'object' && !Array.isArray(value) ? Object.keys(value).sort() : [];
  const usage = responseIsObject && response.usage && typeof response.usage === 'object' ? response.usage : null;
  diagnostic = {
    normalization_path: normalizationPath,
    value_type: valueType(received),
    top_level_keys: objectKeys(received),
    has_body: hasOwn(received, 'body'), body_type: valueType(received?.body), body_keys: objectKeys(received?.body),
    has_data: hasOwn(received, 'data'), data_type: valueType(received?.data), data_keys: objectKeys(received?.data),
    has_response: hasOwn(received, 'response'), response_type: valueType(received?.response), response_keys_wrapper: objectKeys(received?.response),
    has_json: hasOwn(received, 'json'), json_type: valueType(received?.json), json_keys: objectKeys(received?.json),
    normalized_type: valueType(response), normalized_keys: objectKeys(response),
    http_status_if_available: Number(received?.statusCode ?? received?.status ?? 0) || null,
    has_choices: choices.length > 0, choices_count: choices.length,
    first_choice_keys: objectKeys(choice), finish_reason: choice && typeof choice.finish_reason === 'string' ? choice.finish_reason : null,
    has_message: Boolean(message), message_keys: objectKeys(message),
    content_exists: content !== null, content_type: contentType, content_length: contentLength,
    has_choice_text: textPresent, choice_text_type: valueType(choice?.text), choice_text_length: typeof choice?.text === 'string' ? choice.text.length : null,
    has_reasoning_content: hasOwn(message, 'reasoning_content') || hasOwn(choice, 'reasoning_content'),
    usage_present: Boolean(usage),
    prompt_tokens_if_available: Number(usage?.prompt_tokens ?? 0) || null,
    completion_tokens_if_available: Number(usage?.completion_tokens ?? 0) || null,
    total_tokens_if_available: Number(usage?.total_tokens ?? 0) || null
  };
  addTrace(state, 'NEBIUS_HTTP', 'ORCHESTRATOR_HTTP_RESPONSE', responseIsObject && !hasOwn(response, 'error') ? 'OK' : 'ERROR', diagnostic);
  addTrace(state, 'PARSER', 'ORCHESTRATOR_PARSER_INPUT_NORMALIZED', responseIsObject ? 'OK' : 'ERROR', { normalization_path: normalizationPath, value_type: diagnostic.value_type, normalized_type: diagnostic.normalized_type, normalized_keys: diagnostic.normalized_keys });
  addTrace(state, 'PARSER', 'ORCHESTRATOR_FINAL_CONTENT_LOCATED', content === null ? 'ERROR' : 'OK', { source: contentSource, content_type: contentType, content_length: contentLength });
  if (responseIsObject && hasOwn(response, 'error')) throw new Error('Nebius API returned an error response.');
  if (content === null) throw new Error('Nebius response did not contain usable final content.');
  let parsed;
  if (content && typeof content === 'object' && !Array.isArray(content)) {
    parsed = content;
  } else if (typeof content === 'string') {
    let cleaned = content.trim();
    const fence = String.fromCharCode(96).repeat(3);
    if (cleaned.toLowerCase().startsWith(fence + 'json')) {
      cleaned = cleaned.slice(fence.length + 4).trim();
      if (cleaned.endsWith(fence)) cleaned = cleaned.slice(0, -fence.length).trim();
    }
    try {
      parsed = JSON.parse(cleaned);
    } catch (error) {
      addTrace(state, 'PARSER', 'ORCHESTRATOR_JSON_PARSE_RESULT', 'ERROR', { success: false, parsed_keys: [], parse_error_type: 'SYNTAX_ERROR' });
      throw new Error('Nebius final content was not valid JSON.');
    }
  } else {
    throw new Error('Nebius response did not contain usable final content.');
  }
  addTrace(state, 'PARSER', 'ORCHESTRATOR_JSON_PARSE_RESULT', 'OK', { success: true, parsed_keys: parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? Object.keys(parsed).sort() : [], parse_error_type: null });
  const decisionValid = allowed.has(parsed.decision);
  addTrace(state, 'PARSER', 'ORCHESTRATOR_ENUM_VALIDATION', decisionValid ? 'OK' : 'ERROR', { decision: typeof parsed.decision === 'string' ? parsed.decision : null, valid: decisionValid });
  if (!decisionValid) throw new Error('Invalid orchestrator decision: ' + String(parsed.decision));
  if (typeof parsed.reason !== 'string' || !parsed.reason.trim()) throw new Error('Orchestrator reason is required.');
  const requiredInputs = parsed.required_inputs && typeof parsed.required_inputs === 'object' && !Array.isArray(parsed.required_inputs) ? parsed.required_inputs : {};
  return [{ json: { agent: 'ORCHESTRATOR', status: 'SUCCESS', debug_trace: state.debug_trace, decision: parsed.decision, reason: parsed.reason, required_inputs: requiredInputs, error: null } }];
} catch (error) {
  const errorCategory = error.message.startsWith('Nebius API') ? 'API_ERROR' : error.message.includes('usable final content') ? 'FINAL_CONTENT_MISSING' : error.message.includes('valid JSON') ? 'JSON_PARSE_FAILED' : error.message.startsWith('Invalid ') ? 'ENUM_VALIDATION_FAILED' : 'OUTPUT_VALIDATION_FAILED';
  addTrace(state, 'PARSER', 'ORCHESTRATOR_PARSE_FAILURE', 'ERROR', { error_category: errorCategory, diagnostic_available: Boolean(diagnostic) });
  return [{ json: { agent: 'ORCHESTRATOR', status: 'ERROR', debug_trace: state.debug_trace, decision: 'HUMAN_ESCALATION', reason: 'Unable to parse orchestrator decision.', required_inputs: {}, error: error.message + (diagnostic ? ' Diagnostic: ' + JSON.stringify(diagnostic) : ''), diagnostic } }];
}
